/**
 * @name Path traversal vulnerability in importlib_metadata
 * @description User-controlled input flowing to file system operations could lead to path traversal
 * @kind path-problem
 * @problem.severity high
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 *        external/cwe/cwe-023
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@ to file access.", source.getNode(), "user input"

/**
 * @name Package metadata file path traversal
 * @description User-controlled package names or paths flowing to file reading operations
 * @kind path-problem
 * @problem.severity high
 * @id py/package-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PackagePathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for file operations that might read package metadata
    exists(DataFlow::CallCfgNode call |
      (
        // File opening operations
        call = API::builtin("open").getACall() and sink = call.getArg(0) or
        // Path operations
        call = API::moduleImport("pathlib").getMember("Path").getACall() and sink = call.getArg(0) or
        call = API::moduleImport("os").getMember("path").getMember("join").getACall() and sink = call.getArg(0) or
        call = API::moduleImport("os").getMember("path").getMember("exists").getACall() and sink = call.getArg(0) or
        // Package resource access
        call = API::moduleImport("importlib").getMember("resources").getMember("files").getACall() and sink = call.getArg(0)
      )
    )
  }
}

module PackagePathFlow = TaintTracking::Global<PackagePathConfig>;
import PackagePathFlow::PathGraph

from PackagePathFlow::PathNode source, PackagePathFlow::PathNode sink
where PackagePathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Package path traversal from $@.", source.getNode(), "user input"

/**
 * @name Zip slip vulnerability in zip extraction
 * @description Path traversal when extracting zip archives
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("zipfile").getMember(["extract", "extractall"]).getACall() and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("tarfile").getMember(["extract", "extractall"]).getACall() and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("shutil").getMember(["unpack_archive", "make_archive"]).getACall() and
        sink = call.getArg(0)
      )
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Zip slip vulnerability from $@.", source.getNode(), "user input"
